function gazeOn(C, x, y, tt, memo){ var G = C.gazes, q60 = Math.floor(tt * 60); for (var i = 0; i < G.length; i++){ var g = G[i], P;
    if (memo){ var mq = memo[i]; if (!mq || mq.k !== q60){ mq = memo[i] = { k:q60, p:gazePath(C, g, q60 / 60) }; } P = mq.p; } else P = gazePath(C, g, tt);
    for (var k = 0; k < P.length; k++){ var q = P[k]; if (segDist(x, y, q[0], q[1], q[2], q[3]) < g.w) return true; } } return false; }
/* THE LETHE (The Underworld, World 20). A still pool of the river of forgetting lies on the course, a circle r across. Its water
   runs one way, and a ball that ROLLS INTO it forgets which way it was going: the moment it crosses into the pool it is turned to
   the way the Lethe runs, keeping LETHE_KEEP of its pace, and rolls on that way. So where a putt comes out of the pool depends on
   how hard it went in, never on the line it came in on. A ball struck from inside a pool keeps its line until it has rolled out.
   Some pools turn: their way runs round at spin radians a second on the hole's clock (a0 at moment 0), so a putt timed to reach the
   pool as it points at the cup is sent there. Where it is not the river's: a river holds a ball and carries it at its own speed the
   whole way down; the Lethe turns it once, at the edge, and lets it go. Nothing random: a pure function of the clock. */
var LETHE_KEEP = 0.85;
function letheAng(l, tt){ return l.a0 + l.spin * tt; }
function letheAt(C, x, y){ var L = C.lethes; for (var i = 0; i < L.length; i++){ var l = L[i], dx = x - l.x, dy = y - l.y; if (dx * dx + dy * dy < l.r * l.r) return l; } return null; }
/* ZEUS' THUNDERBOLT (Olympus, World 21). A ring of gold is laid on the course where Zeus' bolt falls, r across, and the bolt falls
   on the hole's clock, once a period (at PACE, like everything that moves), phase putting the first strike. As a strike comes the
   ring flashes its warning (the last BOLT_WARN of the period). A ball inside the ring when the bolt falls, rolling through it or
   stopped in it, is thrown: up out of the ring and through the air L feet the way the bolt points (ux, uy), over whatever lies
   between, and set down rolling BOLT_ROLL feet on. A ball that stops in a ring waits there for the bolt, so no putt ever comes to
   rest in one, and the next putt is never played from inside one. Landing in a hazard or off the course loses it, like a ramp's
   jump. Where it is not the cyclone's: the cyclone takes every ball that reaches it and sets it on one mark; the bolt takes only
   the ball that is in the ring at the strike, and throws it a set way from wherever in the ring it was. Nothing random: when it
   falls and where it throws are a pure function of the hole's clock. */
var BOLT_WARN = 0.35, BOLT_FLY = 10, BOLT_ROLL = 1.2;
// how far through its period a bolt is at moment tt: 0 just after a strike, nearing 1 as the next one comes
function boltPh(b, tt){ var u = tt / b.period + b.phase; return u - Math.floor(u); }
// does the bolt fall in the moment (ta, tb]
function boltFalls(b, ta, tb){ return Math.floor(tb / b.period + b.phase) > Math.floor(ta / b.period + b.phase); }
function boltAt(C, x, y){ var Q = C.bolts; for (var i = 0; i < Q.length; i++){ var q = Q[i], dx = x - q.x, dy = y - q.y; if (dx * dx + dy * dy < q.r * q.r) return q; } return null; }
/* DRINK ME AND EAT ME (Wonderland, World 22). A little bottle labelled DRINK ME stands on a round pad, and a little cake marked EAT
   ME in currants on its plate. A ball that rolls onto the bottle shrinks; one that rolls onto the cake grows. The size lasts the
   rest of the putt, or until it rolls onto the other one, and every putt starts at the ball's own size, so the solver's state is
   still the ball and the clock. A SMALL ball (WEE_R across) fits a little door (weeDoor, a door in a wall that stops any other
   ball) and is light, so a slope pushes it WEE_SLOPE times as hard. A BIG ball (BIG_R) is too big for a little door and for the
   cup (it rolls over the hole), cannot pass a gap narrower than itself, and is heavy, so a slope pushes it only BIG_SLOPE as hard.
   Nothing random and nothing on a clock: the size is where the ball has rolled. BR is the radius the walls and bumpers meet,
   BALL_R on every putt that never touches a pad, so no other hole plays any differently. */
var WEE_R = 0.035, BIG_R = 0.34, WEE_SLOPE = 2, BIG_SLOPE = 0.3, WEE_T = 0.06, BR = BALL_R;
function sizerAt(C, x, y){ var Q = C.sizers; if (!Q) return null; for (var i = 0; i < Q.length; i++){ var q = Q[i], dx = x - q.x, dy = y - q.y; if (dx * dx + dy * dy < q.r * q.r) return q; } return null; }
