  var cyc = DAILY_POOL.slice(), cr = mulberry(hstr('cycle:' + Math.floor(dn / L)));
  for (var i = cyc.length - 1; i > 0; i--){ var j = Math.floor(cr() * (i + 1)), t = cyc[i]; cyc[i] = cyc[j]; cyc[j] = t; }
